\label{def: concentration structure}
     A \textbf{concentration structure} on $\mathcal{C}$ is an equivalence relation $\sim$ on $\textup{Mor}_{\mathcal{C}}$, which satisfies the following axioms:

    \begin{enumerate}
        \item $id_A \sim id_B$ for any objects $A, B \in \textup{Ob}_{\mathcal{C}}$. (Identity axiom)

        \item If $f \sim f', g \sim g'$ and both $f\circ g, f' \circ g'$ exist, then $f \circ g \sim f' \circ g'$. (Composition axiom)

        \item For any morphisms $f, g \in \textup{Mor}_{\mathcal{C}}$, there exist some $f' \sim f$ and $ g' \sim g$ such that $f' \circ g'$ exists. (2-Existence axiom)

        \item  For any morphisms $f\sim f', g\sim g', h\sim h', m\sim f\circ g, n \sim g'\circ h'$ we have $f' \circ n \sim m \circ h$ whenever all the compositions are  well defined. (Associativity axiom)
    \end{enumerate}

   If $\sim$ is a concentration structure on $\mathcal{C}$, we will say $(\mathcal{C},\sim)$ is a \textbf{category with concentration}.

\label{def: concentration preserving functor}
    We say a map $F: (\mathcal{C},\sim_{\mathcal{C}}) \rightarrow(\mathcal{D},\sim_{\mathcal{D}}) $ is a \textbf{concentration preserving functor} if the following holds 

    \begin{itemize}
        \item $F$ is a functor between $\mathcal{C}$ and $\mathcal{D}$ in the usual sense.
        \item For any $f,f'\in \textup{Mor}_{\mathcal{C}}$, if $f\sim_{\mathcal{C}}f'$ then $F(f) \sim_{\mathcal{D}}F(f')$. 
    \end{itemize}

\label{def: category S_G}
    Given a group action of $G$ on $\mathcal{S}$, and a $G$-equivariant functor $F: \mathcal{S} \to \mathscr{M}on$, the category of monoids (where $G$ acts trivially on $\mathscr{M}on$), define the category $\mathcal{S}_{G}$ as follows:
    \begin{itemize}
        \item $\textup{Ob}(\mathcal{S}_G) = \textup{Ob}(\mathcal{S})$.
        \item $\textup{Mor}(B, A) = \{(A, \alpha, f): \alpha \in F(A), f \in G, f(B) = A\}$.
        \item Composition is given by $(A, \alpha, f) \circ (B, \beta, g)  = (A, \alpha\beta, fg)$. Here $\alpha\beta$ is well defined because $F$ acts $G$-equivariantly on the objects, i.e. $F(A) = F(f(B)) = F(B)$. 
    \end{itemize}
    The identity morphism $id_{A}$ is given by $(A, e_{F(A)}, \epsilon)$, where $e_{F(A)}$ is the identity in $F(A)$ and $\epsilon$ is the identity in $G$.

\label{def: concentration on S_G}
    We define the concentration structure on $\mathcal{S}_G$ such that $(A, \alpha, f) \sim (B, \beta, g)$ if and only if
    \begin{enumerate}
        \item $(F(\iota_A^C))(\alpha) = (F(\iota_B^C))(\beta)$ for some $C \in \textup{Ob}(\mathcal{S})$.
        \item $f = g$.
    \end{enumerate}

Given an element $g\in \vec{F}$, we define $\iota(g)=[P,\alpha,g]\in B_{\vec{F}}$, where $P, \alpha $ are defined through the following procedures:

    \begin{enumerate}
        \item Find any pair of s.d. partitions $(\mathcal{I}, \mathcal{J})$ representing $g$.
        \item Let $P$ be $\mathcal{E}_+(\mathcal{J})$, the collection of endpoints and midpoints of $\mathcal{J}$ with $+$ sign.
        \item Let $\alpha$ be $\mathfrak{b}(\mathbb{H}_{\mathcal{I}}, \mathbb{H}_{\mathcal{J}})$, the braid induced from the grid diagram $(\mathbb{H}_{\mathcal{I}}, \mathbb{H}_{\mathcal{J}})$ as follows:
    \end{enumerate}

Given a grid diagram $\mathbb{G}$, one obtains a link diagram $\mathcal{L}(\mathbb{G})$ by drawing horizontal and vertical lines joining $X$'s and $O$'s. We turn it into a braid $\mathfrak{b}(\mathbb{G})$ by replacing any vertical line oriented upwards from $O$ to $X$ by two vertical lines, one pointing downwards from the $O$, one pointing downwards to the $X$, and having these new vertical lines pass under all horizontal line segments. One can check that the closure of the braid $\mathfrak{b}(\mathbb{G})$ is exactly the link $\mathcal{L}(\mathbb{G})$. This grid-to-braid operation is also used in \cite{MR2500576}\cite{MR1339757}\cite{MR2232855}, see Figure \ref{fig:grid-to-braid-example} for a specific example.

